    const x = pool.slice(0, n), m = mean(x), h = qt975(n - 1) * sd(x) / Math.sqrt(n);
    return {study: `n = ${n}`, m, lo: m - h, hi: m + h, sig: m - h &gt; 0 || m + h &lt; 0 ? "significant" : "not significant"};
  });
}

